<script setup lang="ts">
import { ref, computed, onMounted } from 'vue';
import { Search, Plus, ScanFace, Pencil, UsersRound, ShieldCheck } from 'lucide-vue-next';
import { api, send, canEdit, type Employee, type Shift } from '../api';
import Modal from '../components/Modal.vue';
import Camera from '../components/Camera.vue';
const employees = ref<Employee[]>([]), shifts = ref<Shift[]>([]), search = ref(''), error = ref(''), busy = ref(false), loading = ref(true), message = ref('');
const edit = ref<Employee | null>(null), showForm = ref(false), enroll = ref<Employee | null>(null), camera = ref<InstanceType<typeof Camera>>(), consent = ref(false), signature = ref('');
const form = ref({ employeeNo: '', firstName: '', lastName: '', department: '', position: '', shiftId: '', active: true });
const filtered = computed(() => employees.value.filter(e => `${e.firstName} ${e.lastName} ${e.employeeNo} ${e.department}`.toLowerCase().includes(search.value.toLowerCase())));
async function load() { try { [employees.value, shifts.value] = await Promise.all([api('/employees'), api('/shifts')]); } catch (e) { error.value = (e as Error).message; } finally { loading.value = false; } }
onMounted(load);
function open(employee?: Employee) { error.value = ''; edit.value = employee ?? null; form.value = employee ? { employeeNo: employee.employeeNo, firstName: employee.firstName, lastName: employee.lastName, department: employee.department, position: employee.position, shiftId: employee.shiftId, active: employee.active } : { employeeNo: '', firstName: '', lastName: '', department: '', position: '', shiftId: shifts.value[0]?.id ?? '', active: true }; showForm.value = true; }
async function save() { busy.value = true; error.value = ''; try { await api(edit.value ? `/employees/${edit.value.id}` : '/employees', send(edit.value ? 'PATCH' : 'POST', form.value)); showForm.value = false; message.value = 'Employee details saved.'; await load(); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
function openEnroll(employee: Employee) { enroll.value = employee; consent.value = false; signature.value = ''; error.value = ''; }
async function register() { busy.value = true; error.value = ''; try { const image = camera.value!.capture(); await api(`/employees/${enroll.value!.id}/enroll`, send('POST', { image, consent: consent.value, signature: signature.value, policyVersion: 'biometric-v1' })); camera.value?.stop(); enroll.value = null; message.value = 'Face enrolled. No camera image was saved.'; await load(); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
async function withdraw() { if (!enroll.value) return; busy.value = true; error.value = ''; try { await api(`/employees/${enroll.value.id}/biometric`, send('DELETE')); enroll.value = null; message.value = 'Consent withdrawn and face template deleted.'; await load(); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
</script>
<template>
  <p v-if="message" class="alert success" role="status">{{ message }} <button class="text-button" @click="message = ''">Dismiss</button></p><p v-if="error && !showForm && !enroll" class="alert error" role="alert">{{ error }}</p>
  <section class="panel"><div class="panel-heading"><div><h2>All employees <span class="count">{{ employees.length }}</span></h2><p>Your municipal workforce, in one directory</p></div><button v-if="canEdit()" class="button primary" @click="open()"><Plus :size="17" /> Add employee</button></div><div class="filter-bar"><label class="search-box"><Search :size="17" /><input v-model="search" type="search" placeholder="Search name, employee no. or department" aria-label="Search employees" /></label><span class="muted small-text">{{ filtered.length }} employees</span></div><div v-if="!filtered.length" class="empty-state"><UsersRound :size="34" /><h3>{{ loading ? 'Loading employees…' : search ? 'No matching employees' : 'Make room for your people' }}</h3><p>{{ search ? 'Try another name or department.' : 'Add your first employee, assign a schedule, then enroll their face with consent.' }}</p><button v-if="!loading && !search && canEdit()" class="button secondary" @click="open()">Add your first employee</button></div><div v-else class="table-wrap"><table><thead><tr><th>Employee</th><th>Department / position</th><th>Schedule</th><th>Enrollment</th><th>Status</th><th v-if="canEdit()">Actions</th></tr></thead><tbody><tr v-for="e in filtered" :key="e.id"><td><div class="person-cell"><div class="avatar">{{ e.firstName[0] }}{{ e.lastName[0] }}</div><div><strong>{{ e.firstName }} {{ e.lastName }}</strong><small>{{ e.employeeNo }}</small></div></div></td><td><strong class="cell-title">{{ e.department }}</strong><small class="cell-subtitle">{{ e.position }}</small></td><td>{{ e.shift.name }}</td><td><span :class="['badge', e.biometric ? 'green' : 'neutral']"><ScanFace :size="13" />{{ e.biometric ? 'Enrolled' : 'Not enrolled' }}</span></td><td><span :class="['badge', e.active ? 'green' : 'neutral']">{{ e.active ? 'Active' : 'Inactive' }}</span></td><td v-if="canEdit()"><div class="row-actions"><button class="icon-button" :aria-label="`Edit ${e.firstName} ${e.lastName}`" @click="open(e)"><Pencil :size="16" /></button><button v-if="e.active" class="icon-button" :aria-label="`Manage face enrollment for ${e.firstName} ${e.lastName}`" @click="openEnroll(e)"><ScanFace :size="18" /></button></div></td></tr></tbody></table></div></section>
  <Modal v-if="showForm" :title="edit ? 'Edit employee' : 'Add employee'" @close="!busy && (showForm = false)"><form @submit.prevent="save"><p v-if="error" class="alert error" role="alert">{{ error }}</p><div class="form-grid"><label>Employee number<input v-model="form.employeeNo" required maxlength="32" pattern="[A-Za-z0-9_\-]+" placeholder="SJ-0001" /></label><label>Department<input v-model="form.department" required maxlength="120" placeholder="Municipal Treasury" /></label><label>First name<input v-model="form.firstName" required maxlength="120" autocomplete="given-name" /></label><label>Last name<input v-model="form.lastName" required maxlength="120" autocomplete="family-name" /></label><label>Position<input v-model="form.position" required maxlength="120" /></label><label>Assigned schedule<select v-model="form.shiftId" required><option v-for="s in shifts" :key="s.id" :value="s.id">{{ s.name }}</option></select></label></div><p v-if="!shifts.length" class="alert error">Create a schedule before adding employees.</p><label v-if="edit" class="check-label"><input v-model="form.active" type="checkbox" /> Employee is active</label><p v-if="edit && !form.active" class="alert info">Deactivating deletes face enrollment and withdraws biometric consent. Attendance history is retained.</p><div class="modal-actions"><button class="button secondary" type="button" :disabled="busy" @click="showForm = false">Cancel</button><button class="button primary" :disabled="busy || !shifts.length">{{ busy ? 'Saving…' : 'Save employee' }}</button></div></form></Modal>
  <Modal v-if="enroll" :title="`Face enrollment · ${enroll.firstName}`" @close="!busy && (enroll = null)"><form @submit.prevent="register"><p v-if="error" class="alert error" role="alert">{{ error }}</p><Camera ref="camera" /><div class="consent-box"><ShieldCheck :size="20" /><div><strong>Biometric processing consent</strong><p>e-RAMS uses a face template to verify your attendance. The image is processed in memory and discarded. Your encrypted template remains until consent is withdrawn or enrollment is removed. Only authorized personnel can manage enrollment. You may decline and ask HR to record attendance manually.</p><p>Contact your municipal HR officer to access or correct your records and to withdraw consent. This pilot notice must be approved by the LGU privacy officer before deployment.</p></div></div><label class="check-label"><input v-model="consent" type="checkbox" required /> I have read this notice and consent to face processing for attendance.</label><label>Employee’s typed signature<input v-model="signature" required minlength="3" maxlength="120" placeholder="Full name of consenting employee" /></label><p class="muted small-text">The employee should review and sign this notice personally. Enrollment replaces any existing template.</p><div class="modal-actions"><button v-if="enroll.biometric" class="button danger" type="button" :disabled="busy" @click="withdraw">Withdraw & delete template</button><button class="button primary" :disabled="busy || !consent">{{ busy ? 'Processing…' : 'Capture & enroll' }}</button></div></form></Modal>
</template>
